from __future__ import annotations

from collections import defaultdict
from math import inf
from typing import Dict, List, Tuple


def _var_x(i: int, j: int) -> str:
    return f"x[{i},{j}]"


def _var_u(c: int) -> str:
    return f"u[{c}]"


def _var_pen() -> str:
    return "pen"


def _all_x_names(inst) -> list[str]:
    names = []
    n = inst.n_customers
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                names.append(_var_x(i, j))
    return names


def _all_u_names(inst) -> list[str]:
    return [_var_u(c) for c in inst.customers]


def variables(inst) -> dict[str, tuple[float, float, str]]:
    vars_: dict[str, tuple[float, float, str]] = {}
    n = inst.n_customers

    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                vars_[_var_x(i, j)] = (0.0, 1.0, "binary")

    for c in inst.customers:
        vars_[_var_u(c)] = (float(inst.demand[c]), float(inst.capacity), "continuous")

    vars_[_var_pen()] = (0.0, 1.0, "continuous")
    return vars_


def structural_variables(inst) -> list[str]:
    return _all_x_names(inst) + _all_u_names(inst)


def _route_load(inst, route) -> float:
    return float(sum(inst.demand[c] for c in route if 1 <= c <= inst.n_customers))


def aux_values(inst, sol) -> dict[str, float]:
    routes = canonical(sol)
    vals: dict[str, float] = {_var_pen(): 0.0}

    # Cumulative loads along the canonical routes
    for route in routes:
        load = 0.0
        for c in route:
            if 1 <= c <= inst.n_customers:
                load += float(inst.demand[c])
                vals[_var_u(c)] = load

    # Default values for customers not present / malformed solutions
    for c in inst.customers:
        vals.setdefault(_var_u(c), float(inst.demand[c]))

    v = violations(inst, sol)
    vals[_var_pen()] = 1.0 if (v["visita"] > 0.0 or v["capacidad"] > 0.0) else 0.0
    return vals


def to_assignment(inst, sol) -> dict[str, float]:
    routes = canonical(sol)
    x: dict[str, float] = {}

    # Initialize all structural vars to 0
    for name in structural_variables(inst):
        x[name] = 0.0

    # Encode routes as depot-rooted paths
    for route in routes:
        prev = 0
        for c in route:
            if 1 <= c <= inst.n_customers:
                x[_var_x(prev, c)] = 1.0
                prev = c
        x[_var_x(prev, 0)] = 1.0

    return x


def from_assignment(inst, x) -> "sol":
    n = inst.n_customers

    # Build successor map from selected arcs; one successor per node chosen greedily
    succ = {}
    for i in range(n + 1):
        best_j = None
        for j in range(n + 1):
            if i != j and float(x.get(_var_x(i, j), 0.0)) > 0.5:
                best_j = j
                break
        if best_j is not None:
            succ[i] = best_j

    routes = []
    visited = set()

    for start in range(1, n + 1):
        if float(x.get(_var_x(0, start), 0.0)) <= 0.5:
            continue
        route = []
        cur = start
        seen = set()
        while 1 <= cur <= n and cur not in seen:
            seen.add(cur)
            visited.add(cur)
            route.append(cur)
            nxt = succ.get(cur, 0)
            cur = nxt
            if cur == 0:
                break
        if route:
            routes.append(tuple(route))

    # Add any unvisited customers as singleton routes to keep a valid neutral solution
    for c in range(1, n + 1):
        if c not in visited:
            routes.append((c,))

    return canonical(routes)


def constraint_families(inst) -> dict[str, list[tuple[dict[str, float], str, float]]]:
    fams: dict[str, list[tuple[dict[str, float], str, float]]] = {
        "visita.entrada": [],
        "visita.salida": [],
        "capacidad.cota_inf": [],
        "capacidad.cota_sup": [],
        "capacidad.transicion": [],
    }

    n = inst.n_customers

    # Visit exactly once: one incoming and one outgoing per customer
    for c in inst.customers:
        coef_in = {}
        coef_out = {}
        for i in range(n + 1):
            if i != c:
                coef_in[_var_x(i, c)] = 1.0
                coef_out[_var_x(c, i)] = 1.0
        fams["visita.entrada"].append((coef_in, "==", 1.0))
        fams["visita.salida"].append((coef_out, "==", 1.0))

    # Capacity/load variables
    for c in inst.customers:
        fams["capacidad.cota_inf"].append(({_var_u(c): 1.0}, ">=", float(inst.demand[c])))
        fams["capacidad.cota_sup"].append(({_var_u(c): 1.0}, "<=", float(inst.capacity)))

    # MTZ-like load propagation
    Q = float(inst.capacity)
    for i in inst.customers:
        for j in inst.customers:
            if i == j:
                continue
            coef = {_var_u(j): 1.0, _var_u(i): -1.0, _var_x(i, j): Q}
            # u_j - u_i + Q x_ij >= d_j
            fams["capacidad.transicion"].append((coef, ">=", float(inst.demand[j])))

    return fams


def objective_terms(inst) -> dict[str, tuple[dict[str, float], float]]:
    coef: dict[str, float] = {}
    n = inst.n_customers

    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                coef[_var_x(i, j)] = float(inst.dist(i, j))

    feasible_upper = 0.0
    for c in inst.customers:
        feasible_upper += 2.0 * float(inst.dist(0, c))
    big_m = feasible_upper + 1.0
    coef[_var_pen()] = big_m

    return {"distancia": (coef, 0.0)}


def variable_groups(inst) -> dict[str, list[str]]:
    n = inst.n_customers
    groups: dict[str, list[str]] = defaultdict(list)

    # Split customers into 4 balanced blocks by index.
    blocks = [list() for _ in range(4)]
    for idx, c in enumerate(inst.customers):
        blocks[idx % 4].append(c)

    # Group arcs by tail customer block; depot-related arcs in block 0.
    for i in range(n + 1):
        if i == 0:
            block_id = 0
        else:
            block_id = (i - 1) % 4
        for j in range(n + 1):
            if i == j:
                continue
            groups[f"arc_{block_id}"].append(_var_x(i, j))

    # Load variables split similarly
    for idx, c in enumerate(inst.customers):
        groups[f"load_{idx % 4}"].append(_var_u(c))

    groups["penalty"].append(_var_pen())

    return dict(groups)
